'use strict';
(() => {
  const $=selector=>document.querySelector(selector);
  const toast=document.createElement('div');toast.className='interaction-toast';toast.setAttribute('role','status');document.body.append(toast);let toastTimer;
  function announce(text){clearTimeout(toastTimer);toast.textContent=text;toast.classList.add('visible');toastTimer=setTimeout(()=>toast.classList.remove('visible'),2800);}

  // Save service ideas locally, separately from the app's saved professionals.
  const saved=new Set();let persistent=true;
  try{const value=JSON.parse(localStorage.getItem('artist-house-saved-services')||'[]');if(Array.isArray(value))value.filter(id=>services.some(service=>service.id===id)).slice(0,6).forEach(id=>saved.add(id));}catch{persistent=false;}
  const heart='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg>';
  const dock=document.createElement('button');dock.type='button';dock.className='saved-dock';dock.innerHTML=heart+'<span></span><b aria-hidden="true">↗</b>';document.body.append(dock);
  const navSaved=document.createElement('button');navSaved.className='nav-saved';navSaved.type='button';$('#navigation .nav-cta').before(navSaved);
  function paintSaved(){document.querySelectorAll('[data-save-service]').forEach(button=>{const active=saved.has(button.dataset.saveService);button.classList.toggle('is-saved',active);button.setAttribute('aria-pressed',String(active));button.setAttribute('aria-label',(active?'Unsave ':'Save ')+(services.find(s=>s.id===button.dataset.saveService)?.name||'service'));});dock.hidden=!saved.size;dock.querySelector('span').textContent='Your saved ideas · '+saved.size;navSaved.textContent='Saved ('+saved.size+')';}
  function persist(){try{localStorage.setItem('artist-house-saved-services',JSON.stringify([...saved]));}catch{persistent=false;}}
  function toggleSave(id){if(saved.has(id)){saved.delete(id);announce('Removed from your saved ideas.');}else{if(saved.size>=6){announce('You can save up to six ideas. Remove one to add another.');return;}saved.add(id);announce('Saved. Open your saved ideas whenever you like.');}persist();paintSaved();}
  function decorateCards(){grid.querySelectorAll('.service-card').forEach(card=>{if(card.parentElement.classList.contains('service-tile'))return;const tile=document.createElement('div');tile.className='service-tile';card.before(tile);tile.append(card);const save=document.createElement('button');save.type='button';save.className='save-service';save.dataset.saveService=card.dataset.serviceId;save.innerHTML=heart;save.addEventListener('click',()=>toggleSave(save.dataset.saveService));tile.append(save);});paintSaved();}
  grid.addEventListener('services:rendered',decorateCards);decorateCards();
  document.addEventListener('artist-house:service-opened',event=>{const button=$('#detail-save');const update=()=>{button.textContent=saved.has(event.detail.id)?'Saved ♥':'Save this service ♡';button.setAttribute('aria-pressed',String(saved.has(event.detail.id)));};button.addEventListener('click',()=>{toggleSave(event.detail.id);update();});update();});
  function showSaved(){
    content.innerHTML='<div class="dialog-body"><p class="eyebrow">A LITTLE INSPIRATION, KEPT CLOSE</p><h2 id="dialog-title">Your saved ideas.</h2><p class="saved-location"></p><div class="saved-list"></div><p class="saved-empty" hidden>Tap a heart on any service to start your collection.</p><button class="button dark saved-explore">Explore more services <span>↗</span></button></div>';
    content.querySelector('.saved-location').textContent=persistent?'Saved in this browser. Book services in the Artist House app.':'Saved for this visit. Book services in the Artist House app.';
    function draw(){const list=content.querySelector('.saved-list');list.replaceChildren();for(const id of saved){const service=services.find(s=>s.id===id);if(!service)continue;const row=document.createElement('div');row.className='saved-row';const image=document.createElement('img');image.src=service.image||'assets/'+id+'.webp';image.alt='';const view=document.createElement('button');view.textContent=service.name;view.addEventListener('click',()=>{showService(service);document.querySelector('.dialog-close').focus();});const remove=document.createElement('button');remove.className='saved-remove';remove.textContent='×';remove.setAttribute('aria-label','Remove '+service.name);remove.addEventListener('click',()=>{toggleSave(id);draw();(list.querySelector('button')||content.querySelector('.saved-explore')).focus();});row.append(image,view,remove);list.append(row);}content.querySelector('.saved-empty').hidden=saved.size!==0;}
    draw();content.querySelector('.saved-explore').addEventListener('click',()=>{dialog.close();scrollToServices();});openDialog();
  }
  dock.addEventListener('click',showSaved);navSaved.addEventListener('click',()=>{closeMenu();showSaved();});
  window.addEventListener('storage',event=>{if(event.key!=='artist-house-saved-services')return;try{const next=JSON.parse(event.newValue||'[]');if(!Array.isArray(next))return;saved.clear();next.filter(id=>services.some(s=>s.id===id)).slice(0,6).forEach(id=>saved.add(id));paintSaved();}catch{}});

  // Two-step chooser: no invented prices or availability, just service inspiration.
  let chosenOccasion='',groups=new Set();
  const occasionCopy={wedding:['wedding-photography','Wedding photography inspiration','For the day you’ll remember.'],party:['festive-makeup','Festive makeup inspiration','A celebration, made yours.'],brand:['brand-content','Brand content inspiration','Your next idea starts here.'],all:['portrait-photography','Portrait inspiration','Follow your curiosity.']};
  function matches(){return services.filter(service=>(!chosenOccasion||chosenOccasion==='all'||service.occasion.includes(chosenOccasion))&&(!groups.size||groups.has(service.group)));}
  function updatePlan(){const count=matches().length;$('#fit-result-hint').textContent=count?count+' service ideas fit your plan.':'No inspiration cards for this combination yet. Try another craft.';$('#fit-submit').disabled=count===0;document.querySelectorAll('[data-fit-group]').forEach(button=>button.setAttribute('aria-pressed',String(groups.has(button.dataset.fitGroup))));}
  function step(number){$('#fit-occasion-step').hidden=number!==1;$('#fit-craft-step').hidden=number!==2;$('#fit-step-label').textContent=number===1?'01 / 02 · YOUR MOMENT':'02 / 02 · YOUR CRAFT';if(number===2)updatePlan();}
  document.querySelectorAll('[data-fit-occasion]').forEach(button=>button.addEventListener('click',()=>{chosenOccasion=button.dataset.fitOccasion;document.querySelectorAll('[data-fit-occasion]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const [image,alt,copy]=occasionCopy[chosenOccasion];$('#fit-image').src='assets/'+image+'.webp';$('#fit-image').alt=alt;$('#fit-photo-label').textContent=copy;$('#fit-next').disabled=false;}));
  document.querySelectorAll('[data-fit-group]').forEach(button=>button.addEventListener('click',()=>{const group=button.dataset.fitGroup;if(groups.has(group))groups.delete(group);else groups.add(group);updatePlan();}));
  $('#fit-next').addEventListener('click',()=>{step(2);$('#fit-craft-step h3').tabIndex=-1;$('#fit-craft-step h3').focus({preventScroll:true});});$('#fit-back').addEventListener('click',()=>step(1));
  $('#fit-reset').addEventListener('click',()=>{chosenOccasion='';groups.clear();document.querySelectorAll('[data-fit-occasion],[data-fit-group]').forEach(button=>button.setAttribute('aria-pressed','false'));$('#fit-next').disabled=true;step(1);});
  $('#fit-submit').addEventListener('click',()=>{document.dispatchEvent(new CustomEvent('artist-house:plan',{detail:{occasion:chosenOccasion,groups:[...groups]}}));$('#fit-finder').open=false;announce('Your service picks are ready. Save any that catch your eye.');});

  // Keyboard- and pointer-accessible instant search suggestions.
  const search=$('#service-search'),form=$('#search-form'),suggestions=document.createElement('div');suggestions.id='service-suggestions';suggestions.className='service-suggestions';suggestions.setAttribute('role','listbox');suggestions.setAttribute('aria-label','Suggested services');suggestions.hidden=true;form.append(suggestions);
  search.setAttribute('role','combobox');search.setAttribute('aria-autocomplete','list');search.setAttribute('aria-controls',suggestions.id);search.setAttribute('aria-expanded','false');let suggested=[],active=-1;
  function hideSuggestions(){suggestions.hidden=true;search.setAttribute('aria-expanded','false');search.removeAttribute('aria-activedescendant');active=-1;}
  function choose(index){const service=suggested[index];if(!service)return;search.value=service.name;hideSuggestions();form.requestSubmit();}
  function showSuggestions(){const words=search.value.toLowerCase().replace(/\breels\b/g,'reel').trim().split(/\s+/).filter(Boolean);if(!words.length){hideSuggestions();return;}suggested=services.filter(service=>words.every(word=>(service.name+' '+service.label+' '+service.group).toLowerCase().includes(word))).slice(0,5);suggestions.replaceChildren();active=-1;search.removeAttribute('aria-activedescendant');if(!suggested.length){hideSuggestions();return;}suggested.forEach((service,index)=>{const option=document.createElement('button');option.type='button';option.id='suggested-service-'+index;option.setAttribute('role','option');option.setAttribute('aria-selected','false');option.tabIndex=-1;const image=document.createElement('img');image.src=service.image||'assets/'+service.id+'.webp';image.alt='';const label=document.createElement('span');label.textContent=service.name;const arrow=document.createElement('span');arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');option.append(image,label,arrow);option.addEventListener('click',()=>choose(index));suggestions.append(option);});suggestions.hidden=false;search.setAttribute('aria-expanded','true');}
  search.addEventListener('input',showSuggestions);search.addEventListener('focus',showSuggestions);form.addEventListener('submit',hideSuggestions);
  search.addEventListener('keydown',event=>{if(event.key==='Escape'){hideSuggestions();return;}if(suggestions.hidden)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();active=(active+(event.key==='ArrowDown'?1:-1)+suggested.length)%suggested.length;[...suggestions.children].forEach((option,index)=>option.setAttribute('aria-selected',String(index===active)));search.setAttribute('aria-activedescendant',suggestions.children[active].id);}else if(event.key==='Enter'&&active>=0){event.preventDefault();choose(active);}});
  document.addEventListener('pointerdown',event=>{if(!form.contains(event.target))hideSuggestions();});

  // Public marketing-only data; no sign-in or private account queries on the landing page.
  let catalogSignature='';
  async function refreshCatalog(){const config=window.ARTIST_HOUSE_CATALOG;if(!config||document.hidden)return;try{const headers={apikey:config.key};const responses=await Promise.all(['service_types?select=key,label&order=key','service_artwork?select=service_key,image_path&order=service_key'].map(route=>fetch(config.url+'/rest/v1/'+route,{headers,signal:AbortSignal.timeout(7000)})));if(responses.some(response=>!response.ok))return;const [names,images]=await Promise.all(responses.map(response=>response.json()));if(!Array.isArray(names)||!Array.isArray(images))return;const signature=JSON.stringify([names,images]);if(signature===catalogSignature)return;catalogSignature=signature;for(const service of services){const name=names.find(row=>row.key===service.id);if(typeof name?.label==='string')service.name=name.label;const image=images.find(row=>row.service_key===service.id);if(image&&/^[a-f0-9-]{36}\/[a-f0-9-]{36}\.jpg$/.test(image.image_path))service.image=config.url+'/storage/v1/object/public/service-artwork/'+image.image_path;else delete service.image;}renderServices();updatePlan();}catch{/* Offline visitors keep the bundled catalog and images. */}}
  void refreshCatalog();setInterval(()=>{void refreshCatalog();},60000);
})();
